fn bdev_get_queue(bdev: *mut block_device) -> *mut request_queue {
return unsafe { (*bdev).bd_queue }; // this is never NULL
}

fn sb_issue_discard(sb: *mut super_block, block: u64, nr_blocks: u64, gfp_mask: u32, flags: u64) -> i32 {
unsafe { blkdev_issue_discard((*sb).s_bdev, block << ((*sb).s_blocksize_bits as i32).wrapping_sub(9), nr_blocks << ((*sb).s_blocksize_bits as i32).wrapping_sub(9), gfp_mask) }
}

fn bdev_limits(bdev: *mut block_device) -> *mut queue_limits {
unsafe { core::ptr::addr_of_mut!((*bdev_get_queue(bdev)).limits) }
}

fn bdev_discard_granularity(bdev: *mut block_device) -> u32 {
unsafe { (*bdev_limits(bdev)).discard_granularity }
}

fn bdev_rot(bdev: *mut block_device) -> bool {
blk_queue_rot!(bdev_get_queue(bdev)) != 0
}

