let mut __seq: u64 = 0;
loop {
__cpu = find_next_bit(cpumask_bits!((unsafe { core::ptr::addr_of_mut!(__cpu_possible_mask) }) as *const cpumask), 64u64, __cpu as u64) as i32;
if (__cpu as u32) >= 64 {
break;
}
let __v0: u64 = per_cpu!(discard_pa_seq, __cpu);
__seq = __seq.wrapping_add(__v0);
__cpu = __cpu.wrapping_add(1);
}
